#include <algorithm>
#include <chrono>
#include <cstdint>
#include <iostream>
#include <numeric>
#include <random>
#include <string>
#include <unordered_map>
#include <vector>
using Clock=std::chrono::steady_clock; static constexpr uint64_t SEED=0xB0D2A018ULL;
static inline uint64_t mix64(uint64_t x){x+=0x9e3779b97f4a7c15ULL;x=(x^(x>>30))*0xbf58476d1ce4e5b9ULL;x=(x^(x>>27))*0x94d049bb133111ebULL;return x^(x>>31);} static inline uint64_t fnv1a(const std::string&s,uint64_t h=1469598103934665603ULL){for(unsigned char c:s){h^=c;h*=1099511628211ULL;}return h;}
struct A{uint32_t rho;uint16_t phi,theta;uint64_t fp;};static inline A enc(const std::string&k,uint32_t M){uint64_t h0=mix64(fnv1a(k)),h1=mix64(h0^0xD6E8FEB86659FD93ULL),h2=mix64(h1^0xA5A35625D3E7E5B9ULL),h3=mix64(h2^0x9E3779B97F4A7C15ULL);return{uint32_t(h0%M),uint16_t(h1),uint16_t(h2),mix64(h0^(h1<<1)^(h2>>1)^h3)};}
struct S{uint64_t key=0,val=0;uint32_t dist=0;bool used=false;};class RH{std::vector<S>s;size_t mask;public:RH(size_t n){size_t c=8;while(c<n*2)c<<=1;s.resize(c);mask=c-1;}void put(uint64_t k,uint64_t v){size_t i=mix64(k)&mask;S cur{k,v,0,true};for(;;){auto&x=s[i];if(!x.used){x=cur;return;}if(x.key==cur.key){x.val=v;return;}if(x.dist<cur.dist)std::swap(x,cur);i=(i+1)&mask;++cur.dist;}}bool get(uint64_t k,uint64_t&v)const{size_t i=mix64(k)&mask;uint32_t d=0;for(;;){auto&x=s[i];if(!x.used||x.dist<d)return false;if(x.key==k){v=x.val;return true;}i=(i+1)&mask;++d;}}size_t bytes()const{return s.capacity()*sizeof(S);}};
class Flat{std::unordered_map<uint64_t,uint64_t>m;public:Flat(size_t n){m.reserve(n*2);}void put(uint64_t k,uint64_t v){m[k]=v;}bool get(uint64_t k,uint64_t&v)const{auto i=m.find(k);if(i==m.end())return false;v=i->second;return true;}size_t bytes()const{return m.bucket_count()*sizeof(void*)+m.size()*32;}};
struct R{uint64_t fp,val;uint16_t phi;};struct P{std::vector<R>r;std::unordered_map<uint16_t,std::vector<uint32_t>>z2;bool use_z2=false;};class Adaptive{uint32_t M;std::vector<P>p;public:Adaptive(uint32_t m):M(m),p(m){}void build(const std::vector<std::string>&ks){std::vector<uint32_t>c(M);for(auto&k:ks)c[enc(k,M).rho]++;for(uint32_t i=0;i<M;++i)p[i].r.reserve(c[i]);for(size_t i=0;i<ks.size();++i){auto a=enc(ks[i],M);p[a.rho].r.push_back({a.fp,i,a.phi});}for(auto&x:p)if(x.r.size()>12){x.use_z2=true;for(uint32_t i=0;i<x.r.size();++i)x.z2[x.r[i].phi].push_back(i);}}bool get(const std::string&k,uint64_t&v)const{auto a=enc(k,M);auto&x=p[a.rho];if(!x.use_z2){for(auto&r:x.r)if(r.fp==a.fp){v=r.val;return true;}return false;}auto it=x.z2.find(a.phi);if(it==x.z2.end())return false;for(auto i:it->second)if(x.r[i].fp==a.fp){v=x.r[i].val;return true;}return false;}size_t bytes()const{size_t b=p.capacity()*sizeof(P);for(auto&x:p){b+=x.r.capacity()*sizeof(R);for(auto&kv:x.z2)b+=sizeof(kv)+kv.second.capacity()*4;}return b;}};
struct Stat{double mean,p99,tput;};template<class F>Stat bench(F&&f,const std::vector<std::string>&ks,const std::vector<size_t>&q){std::vector<double>l;l.reserve(q.size());volatile uint64_t sink=0;auto A0=Clock::now();for(auto i:q){auto a=Clock::now();uint64_t v=0;f(ks[i],v);auto b=Clock::now();sink^=v;l.push_back(std::chrono::duration<double,std::micro>(b-a).count());}auto B=Clock::now();std::sort(l.begin(),l.end());return{std::accumulate(l.begin(),l.end(),0.0)/l.size(),l[size_t(.99*(l.size()-1))],q.size()/std::chrono::duration<double>(B-A0).count()};}
std::vector<std::string>keys(std::string w,size_t N,uint32_t M){std::vector<std::string>o;o.reserve(N);if(w=="hotrho"){uint32_t hot=std::max(1u,M/32);uint64_t c=0;while(o.size()<N){auto k="H"+std::to_string(c++);if(enc(k,M).rho<hot)o.push_back(k);}}else for(size_t i=0;i<N;++i)o.push_back("K_"+std::to_string(i));return o;}
int main(int argc,char**argv){size_t N=argc>1?std::stoull(argv[1]):100000,Q=50000;uint32_t M=2048;std::cout<<"workload,engine,mean_us,p99_us,throughput_ops_s,approx_bytes_per_record\n";for(std::string w:{"sequential","hotrho"}){auto ks=keys(w,N,M);std::vector<A>as;as.reserve(N);for(auto&k:ks)as.push_back(enc(k,M));std::mt19937_64 r(SEED);std::uniform_int_distribution<size_t>d(0,N-1);std::vector<size_t>q(Q);for(auto&x:q)x=d(r);Flat flat(N);for(size_t i=0;i<N;++i)flat.put(as[i].fp,i);auto sf=bench([&](auto&k,uint64_t&v){return flat.get(enc(k,M).fp,v);},ks,q);std::cout<<w<<",flat_unordered,"<<sf.mean<<','<<sf.p99<<','<<sf.tput<<','<<double(flat.bytes())/N<<'\n';RH rh(N);for(size_t i=0;i<N;++i)rh.put(as[i].fp,i);auto sr=bench([&](auto&k,uint64_t&v){return rh.get(enc(k,M).fp,v);},ks,q);std::cout<<w<<",robin_hood,"<<sr.mean<<','<<sr.p99<<','<<sr.tput<<','<<double(rh.bytes())/N<<'\n';Adaptive ad(M);ad.build(ks);auto sa=bench([&](auto&k,uint64_t&v){return ad.get(k,v);},ks,q);std::cout<<w<<",adaptive_hierarchical,"<<sa.mean<<','<<sa.p99<<','<<sa.tput<<','<<double(ad.bytes())/N<<'\n';}}
